def GetDestination(destination_id):
    for destination in DESTINATIONS:
        if destination["id"] == destination_id:
            return destination
    return None


def GetRegionAt(x, y):
    if x < 0 or y < 0 or x >= MAP_WIDTH or y >= MAP_HEIGHT:
        return None
    for start_x, end_x, region_no in PICK_ROWS[y]:
        if start_x <= x < end_x:
            return DESTINATIONS[region_no - 1]["id"]
    return None
